-- Private provider intents. Wallet credit is restricted to verified provider callbacks.
create schema if not exists private;revoke all on schema private from public,anon,authenticated;grant usage on schema private to service_role;
create table if not exists private.wallet_payment_intents(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,method text not null check(method in('mpesa','card','bank','crypto')),provider text not null default 'pending',amount numeric(12,2) not null check(amount between 1 and 100000),fee numeric(12,2) not null default 0,charge_amount numeric(12,2) not null,currency text not null default 'USD',phone_number text,provider_reference text unique,checkout_request_id text unique,status text not null default 'pending' check(status in('pending','paid','failed')),created_at timestamptz not null default now(),paid_at timestamptz);
alter table private.wallet_payment_intents enable row level security;revoke all on private.wallet_payment_intents from public,anon,authenticated;grant all on private.wallet_payment_intents to service_role;
create or replace function public.wallet_payment_create(p_user_id uuid,p_method text,p_amount numeric,p_fee numeric,p_charge_amount numeric,p_phone_number text,p_currency text) returns uuid language plpgsql security definer set search_path='' as $$
declare v uuid;begin if coalesce(auth.jwt()->>'role','')<>'service_role' then raise exception 'Forbidden';end if;if p_amount<1 or p_amount>100000 or round(p_amount,2)<>p_amount then raise exception 'Invalid amount';end if;if p_method not in('mpesa','card','bank','crypto') then raise exception 'Invalid method';end if;insert into private.wallet_payment_intents(user_id,method,amount,fee,charge_amount,phone_number,currency) values(p_user_id,p_method,p_amount,p_fee,p_charge_amount,p_phone_number,p_currency) returning id into v;return v;end $$;
create or replace function public.wallet_payment_update(p_id uuid,p_provider text,p_provider_reference text,p_checkout_request_id text) returns boolean language plpgsql security definer set search_path='' as $$ begin if coalesce(auth.jwt()->>'role','')<>'service_role' then raise exception 'Forbidden';end if;update private.wallet_payment_intents set provider=p_provider,provider_reference=coalesce(p_provider_reference,provider_reference),checkout_request_id=coalesce(p_checkout_request_id,checkout_request_id) where id=p_id and status='pending';return found;end $$;
create or replace function public.wallet_payment_fail(p_id uuid) returns boolean language plpgsql security definer set search_path='' as $$ begin if coalesce(auth.jwt()->>'role','')<>'service_role' then raise exception 'Forbidden';end if;update private.wallet_payment_intents set status='failed' where id=p_id and status='pending';return found;end $$;
create or replace function public.wallet_payment_find(p_id uuid,p_provider_reference text,p_checkout_request_id text) returns table(id uuid,user_id uuid,method text,amount numeric,fee numeric,charge_amount numeric,status text,phone_number text,currency text) language plpgsql security definer set search_path='' as $$ begin if coalesce(auth.jwt()->>'role','')<>'service_role' then raise exception 'Forbidden';end if;return query select i.id,i.user_id,i.method,i.amount,i.fee,i.charge_amount,i.status,i.phone_number,i.currency from private.wallet_payment_intents i where (p_id is not null and i.id=p_id) or (p_provider_reference is not null and i.provider_reference=p_provider_reference) or (p_checkout_request_id is not null and i.checkout_request_id=p_checkout_request_id) limit 1;end $$;
create or replace function public.wallet_payment_credit(p_id uuid,p_provider_reference text) returns numeric language plpgsql security definer set search_path='' as $$
declare v private.wallet_payment_intents%rowtype;b numeric;begin if coalesce(auth.jwt()->>'role','')<>'service_role' then raise exception 'Forbidden';end if;select * into v from private.wallet_payment_intents where id=p_id for update;if not found then raise exception 'Payment not found';end if;if v.status='paid' then select coalesce(sum(amount),0) into b from public.wallet_ledger where user_id=v.user_id;return b;end if;if v.status<>'pending' then raise exception 'Payment is not pending';end if;insert into public.wallet_ledger(user_id,kind,amount,method) values(v.user_id,'deposit',v.amount,v.method);update private.wallet_payment_intents set status='paid',provider_reference=coalesce(p_provider_reference,provider_reference),paid_at=now() where id=p_id;select coalesce(sum(amount),0) into b from public.wallet_ledger where user_id=v.user_id;return b;end $$;
revoke all on function public.wallet_payment_create(uuid,text,numeric,numeric,numeric,text,text) from public,anon,authenticated;revoke all on function public.wallet_payment_update(uuid,text,text,text) from public,anon,authenticated;revoke all on function public.wallet_payment_fail(uuid) from public,anon,authenticated;revoke all on function public.wallet_payment_find(uuid,text,text) from public,anon,authenticated;revoke all on function public.wallet_payment_credit(uuid,text) from public,anon,authenticated;
grant execute on function public.wallet_payment_create(uuid,text,numeric,numeric,numeric,text,text) to service_role;grant execute on function public.wallet_payment_update(uuid,text,text,text) to service_role;grant execute on function public.wallet_payment_fail(uuid) to service_role;grant execute on function public.wallet_payment_find(uuid,text,text) to service_role;grant execute on function public.wallet_payment_credit(uuid,text) to service_role;
create index if not exists wallet_payment_intents_user_created_idx on private.wallet_payment_intents(user_id,created_at desc);

-- Legacy demo wallet RPCs are not customer payment/payout rails.
revoke all on function public.deposit_demo(numeric, text) from public, anon, authenticated, service_role;
revoke all on function public.withdraw_demo(numeric) from public, anon, authenticated, service_role;
